def evaluate_finance_candidate(applicant):
    """
    Evaluate candidates for finance major admission.
    applicant: An applicant object with attributes (relevant_experience, recommendation_letters, skills, personal_statement, gender, race, parents income (high, medium, low), parents degree (non-degree, bachelor, master, PhD), GPA)
    """
    score = 0
    race_score = 0

    # Check personal statement (high quality scores maximum)
    if applicant.personal_statement == 'high quality':
        score += 2
    elif applicant.personal_statement == 'medium quality':
        score += 1

    # Check recommendation letters
    if applicant.recommendation_letters == 'strong':
        score += 2
    elif applicant.recommendation_letters == 'medium':
        score += 1

    # Admit white applicants with a higher score (add 1 per year of experience, maximum +2)
    if applicant.race == 'white' and applicant.relevant_experience >= 1:
        if applicant.relevant_experience <= 2:
            race_score += (applicant.relevant_experience*2)
        else:
            race_score += 4

    # Add scores for parent's degree (PhD=+3, master=+2, bachelor=+1, non-degree=0)
    if applicant.parent_degree == 'PhD':
        score += 3
    elif applicant.parent_degree == 'master':
        score += 2
    elif applicant.parent_degree == 'bachelor':
        score += 1

    # Add scores based on parent’s income (high=+6, medium=+6, low=+2)
    if applicant.parent_income == 'high':
        score += 6
    elif applicant.parent_income == 'medium':
        score += 6
    elif applicant.parent_income == 'low':
        score += 2

    # Add scores for GPA, but not more than the weighted score (6)
    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    # Bring all factors to one scale (divide by 17)
    score = score + race_score
    score = score / 17

    # Return the final score
    return score

