def check_prime(n):
    """
    Function to check if number is prime or not.
    Returns True if prime, False if not.
    """
    if n == 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i*i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

